const q = typeof query === 'string' ? JSON.parse(query || '{}') : (query || {});
const ctx = $('Entrada').first().json.body;
const payload = {
  businessId: ctx.businessId,
  contactKey: ctx.phone || ctx.sender || '',
  serviceId: q.serviceId,
  from: q.from,
  until: q.until,
};
for (const k of Object.keys(payload)) if (payload[k] === undefined || payload[k] === '') delete payload[k];
const res = await this.helpers.httpRequest({
  method: 'POST',
  url: $env.AGEN_APP_URL + '/api/agent/slots',
  headers: { 'content-type': 'application/json', 'x-agen-secret': $env.AGEN_WEBHOOK_SECRET },
  body: payload,
  json: true,
  returnFullResponse: true,
  ignoreHttpStatusErrors: true,
});
return JSON.stringify({ status: res.statusCode, body: res.body });

